ALTER TABLE achievement_chest_source_attestations
 ADD COLUMN native_direction smallint CHECK(native_direction BETWEEN 0 AND 7),
 ADD COLUMN native_approach_mask smallint CHECK(native_approach_mask BETWEEN 0 AND 511),
 ADD COLUMN native_center_blocked boolean,
 ADD COLUMN native_physical_sha256 text CHECK(length(native_physical_sha256)=64);
-- Original GenericActivable GIVE_EMOTE7: 55 placements / 52 emotes.
-- No treasure achievement objective, story completion, item or currency seed.
-- Safe cog=4000 remains raw provenance; no duration/cooldown is inferred.
CREATE TABLE native_generic_chest_script_sources (
 descriptor_id integer NOT NULL, wire_action integer NOT NULL,
 effect_reference integer NOT NULL CHECK(effect_reference>0),
 emote_effect_reference integer NOT NULL, effect_order integer NOT NULL CHECK(effect_order>=0),
 effect_type integer NOT NULL CHECK(effect_type=1), effect_criterion text NOT NULL,
 parameters text[] NOT NULL, group_clx integer NOT NULL CHECK(group_clx<>0),
 source_sha256 text NOT NULL CHECK(length(source_sha256)=64),
 script_sha256 text NOT NULL CHECK(length(script_sha256)=64),
 script_archive_sha256 text NOT NULL CHECK(length(script_archive_sha256)=64),
 catalog_revision text NOT NULL CHECK(length(catalog_revision)=64),
 PRIMARY KEY(descriptor_id,wire_action,effect_reference),
 UNIQUE(descriptor_id,wire_action,emote_effect_reference,effect_order),
 FOREIGN KEY(descriptor_id,wire_action,emote_effect_reference) REFERENCES
 native_generic_emote_effect_sources(descriptor_id,wire_action,effect_reference)
);
